WITH lines AS (SELECT id, created_at, coupon_codes, item.price, item.promo FROM (SELECT id, created_at, coupon_codes, EXPLODE_OUTER(items) AS item FROM carts) x) SELECT created_at, price, ROUND(price / SUM(price) OVER (PARTITION BY promo), 4) AS price_share, COUNT(price) OVER (PARTITION BY promo) AS promo_count_price, ROUND(price / SUM(price) OVER (PARTITION BY promo), 4) AS price_share_2 FROM lines;
